"<user>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$taskR004Hash = (Get-FileHash -LiteralPath '"'project/.elenchus/research/R004-fields.md' -Algorithm SHA256).Hash
"'$taskContractHash = (Get-FileHash -LiteralPath '"'project/new-contract.md' -Algorithm SHA256).Hash
if ("'$taskR004Hash -ne '"'F22B31A34AE3BE9A54645A069DAA48C635FE440772994F1C9C5069508AAEF7B6') { throw 'R004 changed unexpectedly' }
if ("'$taskContractHash -ne '"'75F6F592E2624021D430A6AF98E3F7329825627EE30E722FAD246080BAF1FE8F') { throw 'Contract changed unexpectedly' }
"'$taskIndex = Get-Content -LiteralPath '"'project/.elenchus/research/index.md' -Raw
if (-not "'$taskIndex.Contains('"'| R004 | 샘플 필드의 의미는 무엇인가 | 확정 | 데이터 정규화 | [R004-fields.md](R004-fields.md) |')) { throw 'Original index row changed' }
"'$taskDocuments = @('"'project/.elenchus/topology.md', 'project/.elenchus/research/index.md', 'project/.elenchus/research/R005-access-feasibility.md')
foreach ("'$taskDocument in $taskDocuments) {
  $taskText = Get-Content -LiteralPath $taskDocument -Raw
  foreach ($taskMatch in [regex]::Matches($taskText, '"'\\]\\((["'^)]+)'"\\)')) {
    "'$taskTarget = Join-Path (Split-Path -Parent $taskDocument) $taskMatch.Groups[1].Value
    if (-not (Test-Path -LiteralPath $taskTarget -PathType Leaf)) { throw "Broken reference in $taskDocument" }
  }
}
'"'PASS: R004 and contract unchanged; original index row preserved; all document references resolve.'
